export const InteractiveWalkthrough = ({ steps, onComplete }: { steps: any[], onComplete: () => void }) => {
    const [currentStepIndex, setCurrentStepIndex] = useState(0);

    if (!steps || steps.length === 0) return null;

    const currentStep = steps[currentStepIndex];

    const handleNext = () => {
        if (currentStepIndex < steps.length - 1) {
            setCurrentStepIndex(currentStepIndex + 1);
        } else {
            onComplete();
        }
    };

    const handleSkip = () => {
        onComplete();
    };

    return (
        <div className="walkthrough-overlay" style={{
            position: 'fixed',
            top: 0, left: 0, right: 0, bottom: 0,
            backgroundColor: 'rgba(0, 0, 0, 0.5)',
            zIndex: 9999,
            display: 'flex',
            alignItems: 'center',
            justifyContent: 'center'
        }}>
            {/* Highlight bubble */}
            <div className="speech-bubble" style={{
                background: 'white',
                padding: '24px',
                borderRadius: '12px',
                maxWidth: '400px',
                boxShadow: '0 8px 30px rgba(0,0,0,0.3)',
                position: 'relative',
                fontFamily: 'Inter, sans-serif'
            }}>
                <h3 style={{ marginTop: 0, fontFamily: 'Outfit' }}>{currentStep.title}</h3>
                <p style={{ lineHeight: '1.5', color: '#444' }}>{currentStep.content}</p>

                <div style={{ display: 'flex', justifyContent: 'space-between', alignItems: 'center', marginTop: '20px' }}>
                    <span style={{ fontSize: '12px', color: '#888' }}>Step {currentStepIndex + 1} of {steps.length}</span>
                    <div style={{ display: 'flex', gap: '10px' }}>
                        <button onClick={handleSkip} style={{ background: 'transparent', border: 'none', color: '#666', cursor: 'pointer', minWidth: '44px', minHeight: '44px' }}>Skip</button>
                        <button onClick={handleNext} style={{ background: '#0070f3', color: 'white', border: 'none', padding: '10px 20px', borderRadius: '6px', cursor: 'pointer', minWidth: '44px', minHeight: '44px', fontWeight: 'bold' }}>
                            {currentStepIndex === steps.length - 1 ? 'Finish' : 'Next'}
                        </button>
                    </div>
                </div>
            </div>
        </div>
    );
};

